 3	import java.math.BigDecimal
 4	
 5	data class Sale(val accountId:String,val orderId:String,val currency:String,val amount:BigDecimal)
 6	data class SalesTotal(val accountId:String,val currency:String,val orders:Int,val amount:BigDecimal)
 7	
 8	class SalesReport {
 9	    fun summarize(sales: List<Sale>): List<SalesTotal> {
10	        val uniqueSales = mutableMapOf<SaleKey, Sale>()
11	        for (sale in sales) {
12	            val key = SaleKey(sale.accountId, sale.orderId)
13	            val previous = uniqueSales[key]
14	            if (previous == null) {
15	                uniqueSales[key] = sale
16	            } else {
17	                require(previous.currency == sale.currency && previous.amount.compareTo(sale.amount) == 0) {
18	                    "Conflicting sales for accountId=${sale.accountId}, orderId=${sale.orderId}"
19	                }
20	            }
21	        }
22	
23	        return uniqueSales.values
24	            .groupBy { AccountCurrency(it.accountId, it.currency) }
25	            .map { (key, orders) ->
26	                SalesTotal(
27	                    accountId = key.accountId,
28	                    currency = key.currency,
29	                    orders = orders.size,
30	                    amount = orders.sumOf { it.amount },
31	                )
32	            }
33	            .sortedWith(compareBy<SalesTotal> { it.accountId }.thenBy { it.currency })
34	    }
35	
36	    private data class SaleKey(val accountId: String, val orderId: String)
37	
38	    private data class AccountCurrency(val accountId: String, val currency: String)
39	}
